(() => {
"use strict";
const params=new URLSearchParams(location.search),siteConfig=window.GROCERY_STOREFRONT_CONFIG||{},siteSlug=params.get("site")||siteConfig.siteSlug||"",preview=params.get("preview")==="1";
const root=document.getElementById("storefrontRoot"),toastNode=document.getElementById("sfToast");
const storefrontApi=()=>window.HFNeonBuilderApi||window.WPNeonBuilderApi;
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const money=v=>"৳"+Number(v||0).toLocaleString("en-BD",{maximumFractionDigits:2});
const qs=v=>encodeURIComponent(String(v??""));
let state={website:null,pages:[],documents:[],categories:[],products:[],deliveryZones:[],priceTiers:[],checkoutArea:"",page:"home",cart:[],wishlist:[],lastOrder:null,lastTrackedOrder:null,filters:{category:"all",sort:"featured",search:"",brand:"all",availability:"all"},mobileMenu:false,previewToken:null};
const templateInfo={
 "general-supermarket":{brand:"Daily Basket",eyebrow:"YOUR NEIGHBOURHOOD MARKET",heroImage:"https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1400&q=85",hero:"A better basket starts with better choices.",copy:"Everyday essentials, fresh favourites and pantry staples—thoughtfully selected for the people around your table.",badge:"WEEKLY MARKET PICKS",promise:["Fresh every day","Fair everyday value","Delivery that fits your day"],categoryIcons:["🥬","🥛","🍞","🍚","🥤","🧼"]},
 "fresh-produce":{brand:"Field & Fork",eyebrow:"GROWN WITH CARE · GATHERED WITH PURPOSE",heroImage:"https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=1400&q=85",hero:"Closer to the source. Fresher to your table.",copy:"Seasonal produce, grower stories and beautiful everyday staples—chosen with the land and your kitchen in mind.",badge:"IN SEASON NOW",promise:["Season-led selection","Know your growers","Good food, less fuss"],categoryIcons:["🥕","🍊","🌿","🍅","🥚","🍯"]},
 "express-grocery":{brand:"zipmart",eyebrow:"YOUR QUICK LOCAL STORE",heroImage:"https://images.unsplash.com/photo-1604719312566-8912e9c8a213?auto=format&fit=crop&w=1400&q=85",hero:"Need the good stuff? Get moving.",copy:"Your everyday essentials in a few quick taps. Build your bag, check out and get on with your day.",badge:"QUICK PICKS · QUICK DELIVERY",promise:["Fast add-to-bag","Simple checkout","Local delivery"],categoryIcons:["⚡","🥤","🍫","🥛","🧻","🍌"]},
 "wholesale-bulk":{brand:"Merchant Supply",eyebrow:"PROCUREMENT MADE PRACTICAL",heroImage:"https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?auto=format&fit=crop&w=1400&q=85",hero:"Dependable supply. Better buying decisions.",copy:"A business-first catalogue with clear pack sizes, minimum quantities and a streamlined repeat-order workflow.",badge:"BUSINESS BUYING PORTAL",promise:["Transparent pack sizes","Volume-ready ordering","One clear order sheet"],categoryIcons:["🌾","🛢️","📦","🥫","🧂","🚚"]}
};
const pageTitles={home:"Home",shop:"Shop All",category:"Category",product:"Product Details",search:"Search Results",cart:"Your Basket",checkout:"Checkout","order-confirmation":"Order Confirmation","order-tracking":"Track Order",about:"Our Story",contact:"Contact Us",faq:"FAQs",delivery:"Delivery Information",returns:"Returns & Refunds",privacy:"Privacy Policy",terms:"Terms & Conditions",account:"My Account",wishlist:"Wishlist",offers:"Special Offers",brands:"Brands",recipes:"Recipes & Ideas","recipe-detail":"Recipe Details",journal:"Journal","store-locator":"Find a Store","bulk-enquiry":"Bulk & Business Enquiry"};
function pageUrl(page,extra={}){const p=new URLSearchParams({site:siteSlug,page,...extra});if(preview)p.set("preview","1");const base=siteConfig.basePath||"./";return base+"?"+p.toString();}
function imageUrl(p){return p?.image_url||p?.gallery?.[0]?.url||p?.gallery?.[0]||"";}
function getProduct(id){return state.products.find(p=>p.id===id);}
function canOrderProduct(p){const a=p?.attributes||{};return !!p&&Number(p.stock)>0&&!Boolean(state.website?.settings?.demo_catalog)&&!Boolean(a.demo)&&Boolean(a.inventory_verified);}
function quantityStep(p){return state.website?.template_key==="fresh-produce"&&/^(kg|g|l|ml|litre|liter)$/i.test(String(p?.unit||"").trim())?0.1:1;}
function quantityMinimum(p){return Math.max(quantityStep(p),Number(p?.attributes?.minimum_order_quantity||quantityStep(p)));}
function getCategory(id){return state.categories.find(c=>c.id===id);}
function cartKey(){return "hf-storefront-cart-v2:"+siteSlug;}
function wishKey(){return "hf-storefront-wishlist-v1:"+siteSlug;}
function loadLocal(){try{state.cart=JSON.parse(localStorage.getItem(cartKey())||"[]");}catch(_){state.cart=[];}try{state.wishlist=JSON.parse(localStorage.getItem(wishKey())||"[]");}catch(_){state.wishlist=[];}}
function saveLocal(){try{localStorage.setItem(cartKey(),JSON.stringify(state.cart));localStorage.setItem(wishKey(),JSON.stringify(state.wishlist));}catch(_){notify("Your browser could not save this basket.");}}
function cartCount(){return state.cart.reduce((n,x)=>n+Number(x.quantity||0),0);}
function priceForProduct(p,quantity=1){if(!p)return 0;const tiers=state.priceTiers.filter(t=>t.product_id===p.id&&Number(t.minimum_quantity)<=Number(quantity)).sort((a,b)=>Number(b.minimum_quantity)-Number(a.minimum_quantity));return Number(tiers[0]?.unit_price??p.price);}
function cartTotal(){return state.cart.reduce((n,x)=>{const p=getProduct(x.product_id);return n+(p?priceForProduct(p,x.quantity)*Number(x.quantity):0);},0);}
function deliveryAreas(){const zones=state.deliveryZones||[];if(zones.length)return zones.map(z=>z.name).filter(Boolean);const areas=state.website?.settings?.delivery?.areas||[];return areas.map(x=>typeof x==="string"?x:(x?.name||x?.area||"")).map(x=>String(x||"").trim()).filter(Boolean);}
function deliveryZoneForArea(area){const key=String(area||"").trim().toLowerCase();return key?(state.deliveryZones||[]).find(z=>String(z.normalized_name||z.name||"").trim().toLowerCase()===key)||null:null;}
function deliveryFeeForArea(area){if(!area)return null;const zone=deliveryZoneForArea(area);if(zone)return Number(zone.delivery_fee||0);const allowed=deliveryAreas().some(x=>x.toLowerCase()===String(area).trim().toLowerCase());return allowed?Number(state.website?.settings?.delivery?.default_fee||0):null;}
function minimumOrderForArea(area){return Number(deliveryZoneForArea(area)?.minimum_order||0);}
function updateCheckoutSummary(){const area=root.querySelector("#sfArea")?.value||"";state.checkoutArea=area;const fee=deliveryFeeForArea(area),total=cartTotal(),minimum=minimumOrderForArea(area),feeNode=root.querySelector("[data-summary-delivery]"),totalNode=root.querySelector("[data-summary-total]"),note=root.querySelector("[data-summary-note]"),button=root.querySelector("#sfPlaceOrder");if(feeNode)feeNode.textContent=fee===null?"Choose an area":money(fee);if(totalNode)totalNode.textContent=money(total+(fee||0));const eta=deliveryZoneForArea(area)?.eta_label;if(note)note.textContent=minimum>0&&total<minimum?"Minimum order for this area is "+money(minimum)+". Add "+money(minimum-total)+" more to continue.":(area?"Delivery fee and minimum order are confirmed for this area."+(eta?" Estimated delivery: "+eta+".":""):"Select a delivery area to calculate the final total.");if(button)button.disabled=!area||fee===null||total<minimum;}
function notify(message){toastNode.textContent=message;toastNode.classList.add("is-visible");clearTimeout(notify.timer);notify.timer=setTimeout(()=>toastNode.classList.remove("is-visible"),2400);}
function docFor(page){return state.documents.find(d=>d.page_key===page)?.document||null;}
function pageCopy(page){const doc=docFor(page);return {title:doc?.page?.title||pageTitles[page]||"Page",heading:doc?.content?.heading||doc?.tree?.find(n=>n.type==="section")?.children?.find(n=>n.type==="heading")?.text||"",description:doc?.content?.description||doc?.tree?.find(n=>n.type==="section")?.children?.find(n=>n.type==="paragraph")?.text||""};}
function activeProducts(){return state.products.slice();}
function categoryName(p){return getCategory(p.category_id)?.name||"General";}
function card(p){const img=imageUrl(p),cat=categoryName(p),stock=canOrderProduct(p),template=state.website.template_key,attrs=p.attributes||{},tiers=state.priceTiers.filter(t=>t.product_id===p.id).sort((a,b)=>Number(a.minimum_quantity)-Number(b.minimum_quantity));let meta="";if(template==="fresh-produce"){const facts=[attrs.farm_name,attrs.origin,attrs.grade].filter(Boolean);meta=facts.length?'<div class="sf-card-meta">'+facts.map(esc).join(" · ")+'</div>':"";}else if(template==="wholesale-bulk"){const pack=attrs.pack_size||p.unit||"Pack size not set",minimum=Number(attrs.minimum_order_quantity||1);meta='<div class="sf-card-meta"><span>'+esc(pack)+'</span><span>MOQ '+esc(minimum)+'</span>'+(tiers.length?'<span>Volume rates available</span>':"")+'</div>';}else if(template==="express-grocery"){meta='<div class="sf-card-meta"><span>'+(stock?Number(p.stock).toLocaleString("en-BD")+" available":"Currently unavailable")+'</span></div>';}return '<article class="sf-product-card sf-product-card--'+esc(template)+'"><a class="sf-product-media" href="'+pageUrl("product",{product:p.id})+'">'+(img?'<img loading="lazy" src="'+esc(img)+'" alt="'+esc(p.name)+'">':'<span class="sf-image-fallback">'+esc(p.name.slice(0,2).toUpperCase())+'</span>')+'<span class="sf-product-tag">'+(p.compare_at_price&&Number(p.compare_at_price)>Number(p.price)?"SPECIAL":stock?"AVAILABLE":Number(p.stock)>0?"PREVIEW ONLY":"SOLD OUT")+'</span></a><div class="sf-product-info"><small>'+esc(cat)+'</small><h3><a href="'+pageUrl("product",{product:p.id})+'">'+esc(p.name)+'</a></h3>'+meta+'<button type="button" class="sf-card-wish" data-wish="'+esc(p.id)+'" aria-label="Save '+esc(p.name)+' to wishlist">'+(state.wishlist.includes(p.id)?"♥":"♡")+'</button><div class="sf-product-bottom"><span class="sf-price">'+money(p.price)+'<small> / '+esc(p.unit||"piece")+'</small>'+(p.compare_at_price&&Number(p.compare_at_price)>Number(p.price)?'<del>'+money(p.compare_at_price)+'</del>':"")+'</span><button class="sf-add" data-add="'+esc(p.id)+'" '+(!stock?"disabled":"")+' aria-label="Add '+esc(p.name)+' to basket">'+(stock?(template==="wholesale-bulk"?"Add to order":template==="express-grocery"?"+ Add":"Add to basket"):Number(p.stock)>0?"Preview only":"Sold out")+'</button></div></div></article>';}
function productGrid(products){return products.length?'<div class="sf-product-grid">'+products.map(card).join("")+'</div>':'<div class="sf-empty"><h3>Your product shelf is waiting</h3><p>Add categories and products from the Halal Food admin catalogue to populate this storefront. Sample inventory is not used for real orders.</p><a class="sf-btn secondary" href="'+(preview?"./admin/products-add.html":"#")+'">Manage products</a></div>';}
function pageHead(kicker,title,desc,action=""){return '<header class="sf-page-head"><div><span class="sf-kicker">'+esc(kicker)+'</span><h1>'+esc(title)+'</h1><p>'+esc(desc)+'</p></div>'+action+'</header>';}
function hero(){
 const template=state.website.template_key,t=templateInfo[template]||templateInfo["general-supermarket"],copy=pageCopy("home");
 const heading=copy.heading&&copy.heading!=="A better way to shop, every day"?copy.heading:t.hero;
 const description=copy.description&&copy.description!=="Discover carefully selected favourites, fresh picks and everyday essentials."?copy.description:t.copy;
 const categories=state.categories.slice(0,6),products=activeProducts();
 const heroMarkup='<section class="sf-hero sf-hero--'+esc(template)+'"><div class="sf-hero-copy"><span class="sf-kicker">'+esc(t.eyebrow)+'</span><h1>'+esc(heading)+'</h1><p>'+esc(description)+'</p><a class="sf-btn" href="'+pageUrl("shop")+'">'+(template==="wholesale-bulk"?"Browse trade catalogue":template==="express-grocery"?"Build your basket":"Explore the store")+' ↗</a><div class="sf-hero-trust">'+t.promise.map(x=>'<span>✓ '+esc(x)+'</span>').join("　")+'</div></div><div class="sf-hero-media">'+(state.website.brand?.hero_image||t.heroImage?'<img src="'+esc(state.website.brand?.hero_image||t.heroImage)+'" alt="">':"")+'<span class="sf-hero-badge">'+esc(t.badge)+'</span></div></section>';
 const categoryMarkup='<section class="sf-section sf-home-categories"><div class="sf-section-head"><div><span class="sf-kicker">'+(template==="fresh-produce"?"FROM THE MARKET":"BROWSE BY CATEGORY")+'</span><h2>'+(template==="fresh-produce"?"Explore the harvest":"Find your kind of good")+'</h2></div><a class="sf-btn secondary" href="'+pageUrl("shop")+'">View all</a></div><div class="sf-category-grid">'+(categories.length?categories.map((c,i)=>'<a class="sf-category-tile" href="'+pageUrl("category",{category:c.slug})+'"><span>'+t.categoryIcons[i%t.categoryIcons.length]+'</span><strong>'+esc(c.name)+' ↗</strong></a>').join(""):'<div class="sf-empty"><h3>Categories coming soon</h3><p>Create your store categories in the admin panel.</p></div>')+'</div></section>';
 const featured=(rows,title,kicker,desc)=>'<section class="sf-section"><div class="sf-section-head"><div><span class="sf-kicker">'+esc(kicker)+'</span><h2>'+esc(title)+'</h2><p>'+esc(desc)+'</p></div><a class="sf-btn secondary" href="'+pageUrl("shop")+'">Shop all</a></div>'+productGrid(rows)+'</section>';
 if(template==="fresh-produce"){
   const produce=products.filter(p=>/fruit|vegetable|produce|green|herb|farm/i.test(categoryName(p))).slice(0,8);
   const growers=[...new Set(products.map(p=>p.attributes?.farm_name).filter(Boolean))].slice(0,4);
   const provenance='<section class="sf-section sf-farm-story"><div><span class="sf-kicker">KNOW WHAT YOU BUY</span><h2>Good food starts with good information.</h2><p>Origin, grower and grade details appear when the store supplies verified product information. Seasonal availability is confirmed against the live catalogue.</p></div><div class="sf-farm-facts">'+(growers.length?growers.map(x=>'<span>'+esc(x)+'</span>').join(""):'<span>Origin details supplied by the store</span><span>Seasonal selection</span><span>Clear product information</span>')+'</div></section>';
   return heroMarkup+categoryMarkup+featured(produce.length?produce:products.slice(0,8),"Fresh picks for your table","THE PRODUCE EDIT","Browse produce and farm-led staples from the current catalogue.")+provenance;
 }
 if(template==="express-grocery"){
   return heroMarkup+'<section class="sf-section sf-express-promise"><div><span class="sf-kicker">SHOP IN FEWER STEPS</span><h2>Find it. Add it. Keep moving.</h2><p>Quick product discovery, simple quantities and a basket that stays easy to reach. Delivery coverage is shown only when the store configures it.</p></div><a class="sf-btn" href="'+pageUrl("shop")+'">Shop essentials ↗</a></section>'+categoryMarkup+featured(products.slice(0,8),"Quick picks","EASY TO ADD","Popular items from the current store catalogue.")+'<section class="sf-section sf-express-note"><strong>Your basket stays close.</strong><span>On mobile, the basket shortcut follows you as you shop.</span></section>';
 }
 if(template==="wholesale-bulk"){
   return heroMarkup+'<section class="sf-section sf-b2b-benefits"><div><span class="sf-kicker">BUILT FOR BUSINESS BUYING</span><h2>Plan orders with the details in view.</h2><p>Review pack sizes, minimum quantities and any configured volume rates before you submit a supply request.</p></div><div class="sf-b2b-benefit-grid"><span>Pack-size clarity</span><span>Quantity-led ordering</span><span>Volume pricing where configured</span><span>Saved quotation requests</span></div></section>'+categoryMarkup+quickOrderSheet(12)+'<section class="sf-section sf-b2b-quote-cta"><div><span class="sf-kicker">NEED A FORMAL QUOTE?</span><h2>Send one clear supply request.</h2><p>Share your business details, pack sizes and required quantities. The store team can review the request in the central commerce workspace.</p></div><a class="sf-btn" href="'+pageUrl("bulk-enquiry")+'">Request a quotation ↗</a></section>';
 }
 const hasOffers=products.some(p=>Number(p.compare_at_price)>Number(p.price));
 const promo='<section class="sf-section sf-supermarket-promos"><div class="sf-promo-tile"><span>01 / EVERYDAY BASKET</span><h3>Everything for the week ahead.</h3><p>Browse pantry staples, fresh favourites and household essentials in one place.</p><a href="'+pageUrl("shop")+'">Shop the full range ↗</a></div><div class="sf-promo-tile"><span>02 / REAL CATALOGUE OFFERS</span><h3>'+(hasOffers?"Offers from the current catalogue":"A clear view of every price")+'</h3><p>'+(hasOffers?"See products with a store-configured compare-at price.":"Promotional pricing appears only when the store configures it.")+'</p><a href="'+pageUrl("offers")+'">Explore offers ↗</a></div><div class="sf-promo-tile"><span>03 / HOUSEHOLD TOP-UPS</span><h3>More than the grocery aisle.</h3><p>Find useful everyday items alongside your regular shopping.</p><a href="'+pageUrl("shop")+'">Browse departments ↗</a></div></section>';
 return heroMarkup+promo+categoryMarkup+featured(products.slice(0,8),"Popular picks","THE EVERYDAY EDIT","Products and prices from the store catalogue.")+'<section class="sf-section sf-content-panel"><span class="sf-kicker">A BETTER WAY TO BUY</span><h2>Good products. Clear choices. Thoughtful service.</h2><div class="sf-category-grid">'+t.promise.map((x,i)=>'<div class="sf-category-tile"><span>'+["✦","✓","↗"][i]+'</span><strong>'+esc(x)+'</strong></div>').join("")+'</div></section>';
}
function filteredProducts(){let rows=activeProducts().slice();if(state.filters.category!=="all"){const cat=state.categories.find(c=>c.slug===state.filters.category);rows=rows.filter(p=>p.category_id===cat?.id);}if(state.filters.brand!=="all")rows=rows.filter(p=>String(p.attributes?.brand||"").trim()===state.filters.brand);if(state.filters.availability==="available")rows=rows.filter(p=>Number(p.stock)>0);if(state.filters.availability==="sold-out")rows=rows.filter(p=>Number(p.stock)<=0);if(state.filters.search){const q=state.filters.search.toLowerCase();rows=rows.filter(p=>[p.name,p.description,p.sku,p.attributes?.brand,p.attributes?.barcode,p.attributes?.origin,p.attributes?.farm_name,p.attributes?.pack_size,categoryName(p)].join(" ").toLowerCase().includes(q));}if(state.filters.sort==="price-low")rows.sort((a,b)=>Number(a.price)-Number(b.price));if(state.filters.sort==="price-high")rows.sort((a,b)=>Number(b.price)-Number(a.price));if(state.filters.sort==="name")rows.sort((a,b)=>a.name.localeCompare(b.name));if(state.filters.sort==="stock")rows.sort((a,b)=>Number(b.stock)-Number(a.stock));return rows;}
function shopPage(){const c=state.categories,brands=[...new Set(activeProducts().map(p=>String(p.attributes?.brand||"").trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b));return pageHead("THE FULL RANGE","Shop all products","Search by product, brand, SKU or origin, then narrow the catalogue with practical filters.")+'<div class="sf-toolbar"><div class="sf-filter-row"><button class="sf-chip '+(state.filters.category==="all"?"is-active":"")+'" data-filter-category="all">All</button>'+c.map(x=>'<button class="sf-chip '+(state.filters.category===x.slug?"is-active":"")+'" data-filter-category="'+esc(x.slug)+'">'+esc(x.name)+'</button>').join("")+'</div><div class="sf-filter-controls"><select class="sf-sort" id="sfBrandFilter" aria-label="Filter by brand"><option value="all">All brands</option>'+brands.map(x=>'<option value="'+esc(x)+'" '+(state.filters.brand===x?"selected":"")+'>'+esc(x)+'</option>').join("")+'</select><select class="sf-sort" id="sfAvailabilityFilter" aria-label="Filter by availability"><option value="all">All availability</option><option value="available" '+(state.filters.availability==="available"?"selected":"")+'>In stock</option><option value="sold-out" '+(state.filters.availability==="sold-out"?"selected":"")+'>Sold out</option></select><select class="sf-sort" id="sfSort" aria-label="Sort products"><option value="featured">Featured</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="name">Name</option><option value="stock">Stock availability</option></select></div></div><div id="sfProductResults"><p class="sf-help">'+filteredProducts().length+' product(s) found</p>'+productGrid(filteredProducts())+'</div>';}
function categoryPage(){const slug=params.get("category")||"",cat=state.categories.find(c=>c.slug===slug);const rows=cat?state.products.filter(p=>p.category_id===cat.id):[];return pageHead("SHOP BY CATEGORY",cat?.name||"Category not found",cat?"Explore products in this collection.":"Choose a category from the shop page.",'<a class="sf-btn secondary" href="'+pageUrl("shop")+'">All products</a>')+productGrid(rows);}
function searchPage(){const q=params.get("q")||"";state.filters.search=q;return pageHead("SEARCH THE STORE","Search results",q?'Results for “'+q+'”':'Search the product catalogue.')+'<form class="sf-toolbar" id="sfSearchForm"><input class="sf-sort" style="flex:1;min-width:180px" name="q" value="'+esc(q)+'" placeholder="Search products, categories…" aria-label="Search products"><button class="sf-btn">Search</button></form>'+productGrid(filteredProducts());}
function productTierMarkup(p){const tiers=state.priceTiers.filter(t=>t.product_id===p.id).sort((a,b)=>Number(a.minimum_quantity)-Number(b.minimum_quantity));return tiers.length?'<div class="sf-content-panel" style="margin-top:16px"><h3>Volume pricing</h3><ul>'+tiers.map(t=>'<li>Buy '+esc(t.minimum_quantity)+'+ · '+money(t.unit_price)+' / '+esc(p.unit||"unit")+(t.label?' · '+esc(t.label):"")+'</li>').join("")+'</ul><small>Applicable quantity discount is calculated automatically in your basket and confirmed by the server at checkout.</small></div>':"";}
function productPage(){const p=getProduct(params.get("product"));if(!p)return '<div class="sf-empty"><h3>Product not found</h3><p>This product may be unavailable or removed from the catalogue.</p><a class="sf-btn" href="'+pageUrl("shop")+'">Back to shop</a></div>';const img=imageUrl(p),attrs=p.attributes||{},qtyStep=quantityStep(p),qtyMin=quantityMinimum(p),facts=[["Barcode",attrs.barcode],["Pack size",attrs.pack_size],["Origin",attrs.origin],["Grade",attrs.grade],["Farm / producer",attrs.farm_name],["Expiry date",attrs.expiry_date]].filter(x=>String(x[1]||"").trim()),factsHtml=facts.length?'<ul class="sf-product-facts">'+facts.map(x=>'<li><strong>'+esc(x[0])+'</strong>: '+esc(x[1])+'</li>').join("")+'</ul>':"";return '<div class="sf-product-detail"><div class="sf-gallery-main">'+(img?'<img src="'+esc(img)+'" alt="'+esc(p.name)+'">':'')+'</div><div class="sf-product-copy"><span class="sf-kicker">'+esc(categoryName(p))+'</span><h1>'+esc(p.name)+'</h1><div class="sf-product-price">'+money(p.price)+' <small style="font-size:12px;color:var(--sf-muted)">/ '+esc(p.unit||"piece")+'</small></div><p>'+esc(p.description||"Carefully selected for your everyday needs.")+'</p><p><span class="sf-status-pill">'+(canOrderProduct(p)?"In stock":Number(p.stock)>0?"Preview only — inventory verification required":"Currently unavailable")+'</span>　<small>SKU: '+esc(p.sku||"—")+'</small></p>'+(p.attributes?.minimum_order_quantity?'<p>Minimum order: '+qtyMin+' '+esc(p.unit||"units")+'</p>':'')+factsHtml+productTierMarkup(p)+'<div class="sf-product-actions"><label class="sf-qty"><button type="button" data-qty="-1">−</button><input id="sfProductQty" type="number" min="'+qtyMin+'" step="'+qtyStep+'" max="'+Math.max(qtyMin,Number(p.stock))+'" value="'+qtyMin+'"><button type="button" data-qty="1">+</button></label><button class="sf-btn" data-add="'+esc(p.id)+'" '+(!canOrderProduct(p)?"disabled":"")+'>'+ (state.website.template_key==="wholesale-bulk"?"Add to order":"Add to basket")+'</button><button class="sf-btn secondary" data-buy-now="'+esc(p.id)+'" '+(!canOrderProduct(p)?"disabled":"")+'>'+ (state.website.template_key==="wholesale-bulk"?"Request supply":"Buy now")+'</button></div><button class="sf-chip" data-wish="'+esc(p.id)+'">'+(state.wishlist.includes(p.id)?"♥ Saved to wishlist":"♡ Save to wishlist")+'</button><div class="sf-content-panel" style="margin-top:24px"><h3>Product information</h3><p>'+esc(p.description||"Product information will be updated by the store owner.")+'</p>'+factsHtml+'</div></div></div><section class="sf-section"><div class="sf-section-head"><h2>You may also like</h2></div>'+productGrid(state.products.filter(x=>x.id!==p.id&&x.category_id===p.category_id).slice(0,4))+'</section>';}
function cartRows(){return state.cart.map(item=>{const p=getProduct(item.product_id);if(!p)return "";const unitPrice=priceForProduct(p,item.quantity),step=quantityStep(p),minimum=quantityMinimum(p);return '<div class="sf-cart-row"><a href="'+pageUrl("product",{product:p.id})+'">'+(imageUrl(p)?'<img src="'+esc(imageUrl(p))+'" alt="">':'<div class="sf-product-media"></div>')+'</a><div><h3><a href="'+pageUrl("product",{product:p.id})+'">'+esc(p.name)+'</a></h3><small>'+money(unitPrice)+' / '+esc(p.unit||"piece")+(unitPrice<Number(p.price)?' · volume price applied':"")+'</small><div class="sf-cart-controls"><button data-cart-qty="-1" data-product="'+esc(p.id)+'">−</button><input class="sf-cart-quantity" type="number" data-cart-input data-product="'+esc(p.id)+'" min="'+minimum+'" max="'+Number(p.stock)+'" step="'+step+'" value="'+Number(item.quantity)+'" aria-label="Quantity for '+esc(p.name)+'"><button data-cart-qty="1" data-product="'+esc(p.id)+'">+</button><button data-remove="'+esc(p.id)+'" aria-label="Remove product">Remove</button></div></div><strong>'+money(unitPrice*Number(item.quantity))+'</strong></div>';}).join("");}
function cartPage(){if(!cartCount())return '<div class="sf-empty"><h3>Your basket is taking a breather</h3><p>Find something good and add it to your basket.</p><a class="sf-btn" href="'+pageUrl("shop")+'">Start shopping</a></div>';return pageHead("YOUR SELECTION","Your basket","Review quantities and make sure everything is just right.")+'<div class="sf-cart-layout"><div class="sf-cart-list">'+cartRows()+'</div>'+summaryCard(false)+'</div>';}
function summaryCard(checkout=false){const area=checkout?(state.checkoutArea||""):"",delivery=deliveryFeeForArea(area),total=cartTotal();return '<aside class="sf-summary"><h3>Order summary</h3><div class="sf-summary-line"><span>Items ('+cartCount()+')</span><b>'+money(total)+'</b></div><div class="sf-summary-line"><span>Delivery estimate</span><b data-summary-delivery>'+(delivery===null?"Choose at checkout":money(delivery))+'</b></div><div class="sf-summary-total"><span>Total</span><strong data-summary-total>'+money(total+(delivery||0))+'</strong></div><small data-summary-note style="color:var(--sf-muted)">'+(area?"Delivery fee calculated for selected area.":"Choose a delivery area at checkout to calculate the final charge.")+'</small><div style="margin-top:18px">'+(checkout?'<button class="sf-btn" type="submit" form="sfCheckoutForm" style="width:100%">Place COD order →</button>':'<a class="sf-btn" style="width:100%" href="'+pageUrl("checkout")+'">Continue to checkout →</a>')+'</div><p><a href="'+pageUrl("shop")+'">← Continue shopping</a></p></aside>';}
function checkoutPage(){
  if(!cartCount())return cartPage();
  const areas=deliveryAreas(),options=areas.length?areas.map(x=>'<option value="'+esc(x)+'" '+(state.checkoutArea===x?'selected':'')+'>'+esc(x)+'</option>').join(""):'<option value="" disabled selected>Delivery areas are not configured</option>';
  const deliveryMessage=state.deliveryZones.length?"Delivery charges and minimum order values are configured by delivery area.":"The store has not configured any delivery areas yet. Checkout is unavailable until the owner adds real delivery zones.";const substitutionField=state.website.template_key==="fresh-produce"?'<div class="sf-field full"><label for="sfSubstitution">If a produce item is unavailable</label><select id="sfSubstitution" name="substitution"><option value="contact">Contact me before making a substitution</option><option value="similar">Choose the closest available alternative</option><option value="none">Do not substitute unavailable items</option></select></div>':"";
  return pageHead("ALMOST THERE","Checkout","Select a delivery area served by this store. The final delivery fee and minimum order are calculated from the store's delivery settings.")+'<div class="sf-checkout-layout"><form class="sf-form-card" id="sfCheckoutForm"><h3>Delivery details</h3><div class="sf-form-grid"><div class="sf-field"><label for="sfName">Full name *</label><input id="sfName" name="name" required maxlength="120" autocomplete="name"></div><div class="sf-field"><label for="sfPhone">Phone number *</label><input id="sfPhone" name="phone" required maxlength="24" autocomplete="tel" inputmode="tel"></div><div class="sf-field full"><label for="sfAddress">Full delivery address *</label><textarea id="sfAddress" name="address" required maxlength="600" autocomplete="street-address"></textarea></div><div class="sf-field"><label for="sfArea">Delivery area *</label><select id="sfArea" name="area" required '+(areas.length?"":"disabled")+'><option value="" disabled '+(state.checkoutArea?"":"selected")+'>Choose your delivery area</option>'+options+'</select></div><div class="sf-field"><label for="sfPostcode">Postcode</label><input id="sfPostcode" name="postcode" maxlength="20" autocomplete="postal-code"></div><div class="sf-field full"><label for="sfNotes">Delivery notes</label><textarea id="sfNotes" name="notes" maxlength="1000" placeholder="Optional instructions"></textarea></div>'+substitutionField+'</div><div class="sf-content-panel"><strong>Payment method</strong><p>Cash on delivery (COD). Pay when your order arrives.</p></div><p class="sf-help">'+esc(deliveryMessage)+'</p><p><label><input type="checkbox" required> I confirm that my delivery information is correct.</label></p><button class="sf-btn" id="sfPlaceOrder" type="submit" '+(areas.length&&state.checkoutArea&&deliveryFeeForArea(state.checkoutArea)!==null&&cartTotal()>=minimumOrderForArea(state.checkoutArea)?"":"disabled")+'>Place COD order</button><p id="sfCheckoutError" role="alert" style="color:#b42318"></p></form>'+summaryCard(true)+'</div>';
}
function orderConfirmation(){const order=state.lastOrder||(()=>{try{return JSON.parse(sessionStorage.getItem("hf-last-order:"+siteSlug)||"null");}catch(_){return null;}})();if(!order)return '<div class="sf-empty"><h3>No recent order in this browser</h3><p>Use Track Order to look up an existing order.</p><a class="sf-btn" href="'+pageUrl("order-tracking")+'">Track an order</a></div>';return '<div class="sf-content-panel" style="text-align:center;padding:clamp(28px,6vw,70px)"><span style="font-size:46px">✓</span><span class="sf-kicker">ORDER RECEIVED</span><h1 style="font-family:var(--sf-display);font-size:clamp(34px,5vw,54px)">Thank you. We have your order.</h1><p>Your order number is</p><h2 style="font-size:26px;color:var(--sf-primary)">'+esc(order.order_number)+'</h2><p>Total: <strong>'+money(order.total)+'</strong> · Cash on delivery</p><p>Keep this order number and your phone number to track progress.</p><a class="sf-btn" href="'+pageUrl("order-tracking",{order:order.order_number})+'">Track your order</a></div>';}
function trackingPage(){return pageHead("ORDER SUPPORT","Track your order","Enter the order number and the phone number used at checkout.")+'<div class="sf-content-panel"><form id="sfTrackForm" class="sf-form-grid"><div class="sf-field"><label for="sfOrderNumber">Order number</label><input id="sfOrderNumber" name="order" value="'+esc(params.get("order")||"")+'" required placeholder="HF-XXXXXXXXXX"></div><div class="sf-field"><label for="sfTrackPhone">Phone number</label><input id="sfTrackPhone" name="phone" required inputmode="tel"></div><div class="sf-field full"><button class="sf-btn">Track order</button></div></form><div id="sfTrackResult"></div></div>';}function contentPage(key){
const copy=pageCopy(key),title=copy.title||pageTitles[key],brand=state.website.brand||{},settings=state.website.settings||{},delivery=settings.delivery||{},contact=settings.contact||{};
const phone=brand.phone||contact.phone||"",email=brand.email||contact.email||"",address=brand.address||contact.address||"",hours=contact.hours||settings.business_hours||"Contact the store to confirm service hours.";
const details={
about:["Our promise","Shopping should feel clear, personal and dependable. We select useful products, keep product information straightforward and make ordering simple.","This storefront is powered by a live catalogue. Product availability, pricing and delivery details are supplied by the store operator.",["Thoughtful product selection","Clear prices and availability","Local customer support"]],
contact:["Get in touch","Our team can help with product questions, order updates, delivery details and business enquiries.","Choose the contact method below. For an existing order, keep your order number and checkout phone number ready.",["Product and stock questions","Order and delivery support","Wholesale and business enquiries"]],
faq:["A few helpful answers","Quick answers about shopping, orders, delivery and payment.","If your question is not covered here, contact the store team.",["How do I place an order?","Add available products to your basket, enter your delivery details and place a cash-on-delivery order.","Can I change or cancel an order?","Contact the store as soon as possible with your order number. Changes depend on the fulfilment status.","How do I track delivery?","Use Track Order with the order number and phone number supplied at checkout.","When do I pay?","This storefront currently supports cash on delivery. Pay when your order arrives."]],
delivery:["Delivery made clearer","Delivery areas, fees and timing are configured by the store operator.","The final delivery fee is included in the order summary. The store may contact you to confirm availability before dispatch.",["Delivery areas",...(Array.isArray(delivery.areas)?delivery.areas.map(x=>typeof x==="string"?x:x.name||x.area||"Service area"):["Contact the store to confirm your area."]) ,"Default delivery fee: "+money(delivery.default_fee||0),delivery.estimated_days? "Estimated delivery: "+delivery.estimated_days:"Delivery timing is confirmed by the store."]],
returns:["Our returns approach","If something is not right with your order, contact the store with your order number.","Return eligibility and refund arrangements depend on product condition and the store's published policy. Please contact the store before returning an item.",["Share your order number","Explain the issue and include relevant product details","Agree the return arrangement with the store"]],
privacy:["Your information matters","The store uses your contact and delivery details to process orders, coordinate fulfilment and provide customer support.","Order information is stored in the store's private commerce database and is not displayed publicly. Contact the store for privacy-related requests.",["Contact details are used for order fulfilment","Order lookup requires the order number and checkout phone number","Do not submit payment card or password information in delivery notes"]],
terms:["Using this store","By placing an order, you confirm that the information supplied is accurate and that you are authorized to receive the order.","Prices, stock availability, delivery fees and fulfilment times may change. Orders are subject to store confirmation. Cash on delivery is the available payment method unless the store publishes another supported method.",["Product availability is confirmed against live stock at checkout","The store may contact you to verify delivery details","Order status is available through Track Order"]],
account:["Your orders, made easier","You can look up an order using the order number and phone number supplied at checkout.","A customer account is not required for cash-on-delivery checkout. Use the secure order lookup to see fulfilment progress.",["Keep your order number","Use the same phone number entered at checkout","Contact support if your order details do not match"]],
wishlist:["Your saved picks","Products you save stay in this browser on this device.","Your wishlist is a convenience feature and does not reserve stock or place an order.",["Open a product and choose Save to wishlist","Return here to review saved products","Add available items to your basket when you are ready"]]
};
const d=details[key]||details.about;
const list=d.slice(3).flat(Infinity);
const listHtml=key==="faq"?list.reduce((html,item,index)=>index%2===0?html+'<details class="sf-faq-item"><summary>'+esc(item)+'</summary><p>'+esc(list[index+1]||"Contact the store for details.")+'</p></details>':html,""):list.length?'<ul>'+list.map(x=>'<li>'+esc(x)+'</li>').join("")+'</ul>':"";
let contactHtml="";
if(key==="contact"){
contactHtml='<div class="sf-category-grid">'+(phone?'<a class="sf-category-tile" href="tel:'+esc(phone)+'"><span>☎</span><strong>Call the store</strong><small>'+esc(phone)+'</small></a>':"")+(email?'<a class="sf-category-tile" href="mailto:'+esc(email)+'"><span>✉</span><strong>Email the store</strong><small>'+esc(email)+'</small></a>':"")+(address?'<div class="sf-category-tile"><span>⌖</span><strong>Store address</strong><small>'+esc(address)+'</small></div>':"")+'<div class="sf-category-tile"><span>◷</span><strong>Service hours</strong><small>'+esc(hours)+'</small></div></div>';
}
if(key==="delivery"){
contactHtml='<div class="sf-category-grid"><div class="sf-category-tile"><span>৳</span><strong>Delivery fee</strong><small>'+money(delivery.default_fee||0)+'</small></div><div class="sf-category-tile"><span>⌖</span><strong>Service areas</strong><small>'+esc(Array.isArray(delivery.areas)&&delivery.areas.length?delivery.areas.map(x=>typeof x==="string"?x:x.name||x.area||"").filter(Boolean).join(", "):"Confirm with the store")+'</small></div></div>';
}
const fallback=pageHead(key==="faq"?"CUSTOMER HELP":key==="contact"?"CUSTOMER SUPPORT":"THE STORE",title,copy.description||d[0])+'<div class="sf-content-panel"><span class="sf-kicker">'+esc(d[0])+'</span><h2>'+esc(copy.heading||d[0])+'</h2><p>'+esc(d[1])+'</p><p>'+esc(d[2])+'</p>'+listHtml+contactHtml+(key==="contact"&&email?'<p><a class="sf-btn" href="mailto:'+esc(email)+'?subject='+encodeURIComponent("Store enquiry")+'">Email the store</a></p>':"")+(key==="account"?'<a class="sf-btn" href="'+pageUrl("order-tracking")+'">Track an order</a>':"")+(key==="returns"||key==="faq"?'<p><a class="sf-btn secondary" href="'+pageUrl("contact")+'">Contact support</a></p>':"")+'</div>';

const doc=docFor(key),content=doc?.content||{},blocks=Array.isArray(content.blocks)?content.blocks:[],faqs=Array.isArray(content.faqs)?content.faqs:[];
const renderRichBlock=b=>'<section class="sf-rich-block"><h2>'+esc(b.heading||"")+'</h2>'+(Array.isArray(b.paragraphs)?b.paragraphs.map(p=>'<p>'+esc(p)+'</p>').join(""):"")+(Array.isArray(b.bullets)?'<ul>'+b.bullets.map(x=>'<li>'+esc(x)+'</li>').join("")+'</ul>':"")+(Array.isArray(b.faqs)?b.faqs.map(x=>'<details class="sf-faq-item"><summary>'+esc(x.question)+'</summary><p>'+esc(x.answer)+'</p></details>').join(""):"")+'</section>';
const richContent=blocks.map(renderRichBlock).join("")+(faqs.length?'<section class="sf-rich-block"><h2>Frequently asked questions</h2>'+faqs.map(x=>'<details class="sf-faq-item"><summary>'+esc(x.question)+'</summary><p>'+esc(x.answer)+'</p></details>').join("")+'</section>':"");
if(blocks.length||faqs.length){const cta=key==="account"?'<a class="sf-btn" href="'+pageUrl("order-tracking")+'">Track an order</a>':key==="contact"?'<a class="sf-btn secondary" href="'+pageUrl("order-tracking")+'">Order support & tracking</a>':key==="bulk-enquiry"?'<a class="sf-btn" href="'+pageUrl("bulk-enquiry")+'">Open business enquiry</a>':"";return pageHead(key==="faq"?"CUSTOMER HELP":key==="contact"?"CUSTOMER SUPPORT":"THE STORE",title,copy.description||d[0])+'<div class="sf-content-panel sf-rich-content">'+richContent+contactHtml+(cta?'<div class="sf-rich-cta">'+cta+'</div>':"")+'</div>';}
return fallback;
}
function offersPage(){const rows=activeProducts().filter(p=>Number(p.compare_at_price)>Number(p.price));return pageHead("THE GOOD VALUE EDIT","Special offers","Offers are calculated from the live product prices and compare-at prices in your catalogue.")+productGrid(rows);}
function brandsPage(){const brands=[...new Set(activeProducts().map(p=>String(p.attributes?.brand||"").trim()).filter(Boolean))];return pageHead("MEET THE MAKERS","Brands","Discover the makers and product ranges carried by this store.")+(brands.length?'<div class="sf-category-grid">'+brands.map(b=>'<a class="sf-category-tile" href="'+pageUrl("search",{q:b})+'"><span>✦</span><strong>'+esc(b)+' ↗</strong></a>').join("")+'</div>':'<div class="sf-empty"><h3>Brand directory is being curated</h3><p>Add brand names to product attributes in the admin catalogue to show them here.</p></div>')+productGrid(activeProducts().slice(0,4));}
function recipesPage(){const copy=pageCopy("recipes"),items=docFor("recipes")?.content?.recipes||[],descriptions=["A practical idea built around familiar pantry ingredients and a few fresh additions.","A simple combination for a balanced everyday meal. Adjust ingredients to your taste.","A flexible meal-prep idea for busy weekdays and shared tables.","A quick way to use seasonal ingredients before your next shop."];return pageHead("IDEAS FOR YOUR TABLE",copy.title||"Recipes & ideas",copy.description||"Inspiration for everyday cooking.")+'<div class="sf-content-panel"><h2>'+esc(copy.heading||"Cook something lovely")+'</h2><p>Explore approachable ideas, then browse the catalogue for ingredients and everyday favourites.</p></div><section class="sf-section"><div class="sf-section-head"><div><span class="sf-kicker">FROM OUR KITCHEN</span><h2>Ideas to try</h2></div></div><div class="sf-category-grid">'+(items.length?items.map((name,i)=>'<a class="sf-category-tile" href="'+pageUrl("recipe-detail",{recipe:qs(name)})+'"><span>'+["🥗","🍲","🥕","🍞"][i%4]+'</span><strong>'+esc(name)+' ↗</strong><small>'+esc(descriptions[i%descriptions.length])+'</small></a>').join(""):'<p>Recipe ideas are being prepared.</p>')+'</div></section><section class="sf-section"><div class="sf-section-head"><h2>Shop the ingredients</h2><a class="sf-btn secondary" href="'+pageUrl("shop")+'">View all</a></div>'+productGrid(activeProducts().slice(0,8))+'</section>';}
function recipeDetailPage(){const copy=pageCopy("recipe-detail");return pageHead("FROM THE RECIPE JOURNAL",copy.title||"Recipe details",copy.description||"A recipe story from the store.")+'<div class="sf-content-panel"><h2>'+esc(copy.heading||"Ingredients and method")+'</h2><p>Recipe ingredients, preparation steps and serving notes can be written and saved in the page editor. Related products from the live catalogue are shown below.</p></div><section class="sf-section">'+productGrid(activeProducts().slice(0,4))+'</section>';}
function journalPage(){const copy=pageCopy("journal"),posts=docFor("journal")?.content?.posts||[],slug=params.get("article"),article=posts.find(p=>p.slug===slug);if(article){return pageHead("THE STORE JOURNAL",article.title,article.excerpt,'<a class="sf-btn secondary" href="'+pageUrl("journal")+'">← All stories</a>')+'<article class="sf-blog-article">'+(article.image_url?'<img class="sf-blog-cover" src="'+esc(article.image_url)+'" alt="'+esc(article.title)+'">':"")+'<div class="sf-blog-meta">'+esc(article.category||"Journal")+' · '+esc(article.read_time||"3 min read")+'</div>'+(article.body||[]).map(p=>'<p>'+esc(p)+'</p>').join("")+'<div class="sf-blog-end"><a class="sf-btn" href="'+pageUrl("shop")+'">Explore products</a><a class="sf-btn secondary" href="'+pageUrl("journal")+'">More stories</a></div></article>';}return pageHead("NOTES, STORIES & UPDATES",copy.title||"Journal",copy.description||"Stories and useful updates from the store.")+'<div class="sf-content-panel"><h2>'+esc(copy.heading||"From our world")+'</h2><p>Practical guides and ideas selected for this store and its customers.</p></div><section class="sf-section"><div class="sf-blog-grid">'+(posts.length?posts.map(p=>'<article class="sf-blog-card">'+(p.image_url?'<a href="'+pageUrl("journal",{article:p.slug})+'"><img loading="lazy" src="'+esc(p.image_url)+'" alt="'+esc(p.title)+'"></a>':"")+'<div class="sf-blog-card-body"><div class="sf-blog-meta">'+esc(p.category||"Journal")+' · '+esc(p.read_time||"3 min read")+'</div><h2><a href="'+pageUrl("journal",{article:p.slug})+'">'+esc(p.title)+'</a></h2><p>'+esc(p.excerpt)+'</p><a class="sf-text-link" href="'+pageUrl("journal",{article:p.slug})+'">Read story ↗</a></div></article>').join(""):'<div class="sf-empty"><h3>Stories are being prepared</h3><p>Check back soon for new articles.</p></div>')+'</div></section>';}
function storeLocatorPage(){const delivery=state.website.settings?.delivery||{},areas=Array.isArray(delivery.areas)?delivery.areas:[];return pageHead("LOCAL SERVICE","Find a store or delivery area","Check the locations and areas configured by the store.")+'<div class="sf-content-panel"><h2>Where we serve</h2>'+(areas.length?'<ul>'+areas.map(x=>'<li>'+esc(typeof x==="string"?x:x.name||x.area||"Service area")+'</li>').join("")+'</ul>':'<p>Verified service zones have not been configured yet. The store owner must add real delivery areas and pickup addresses before this page can publish location details.</p>')+'<p>'+esc(delivery.note||"Delivery coverage is confirmed by the store at checkout.")+'</p><a class="sf-btn secondary" href="'+pageUrl("contact")+'">Ask about delivery</a></div>';}
function quickOrderSheet(limit=150){const rows=activeProducts().slice(0,Math.max(1,Math.min(150,Number(limit)||150))).map(p=>'<tr data-bulk-row data-bulk-name="'+esc((p.name+" "+(p.sku||"")).toLowerCase())+'"><td>'+esc(p.name)+'<br><small>'+esc(p.sku||"No SKU")+'</small></td><td>'+money(priceForProduct(p,1))+' / '+esc(p.unit||"unit")+(state.priceTiers.some(t=>t.product_id===p.id)?'<br><small>Volume pricing available</small>':"")+'</td><td>'+Number(p.stock).toLocaleString("en-BD")+'</td><td><input class="sf-bulk-qty" type="number" min="0" max="'+Number(p.stock)+'" step="any" value="0" data-bulk-qty="'+esc(p.id)+'" aria-label="Quantity for '+esc(p.name)+'" '+(Number(p.stock)<=0?"disabled":"")+'></td></tr>').join("");return '<section class="sf-section"><div class="sf-section-head"><div><span class="sf-kicker">BUSINESS BUYING</span><h2>Quick bulk order sheet</h2><p>Enter quantities for multiple products, then add them to one basket. Volume prices are applied automatically.</p></div></div><div class="sf-toolbar"><input class="sf-sort" id="sfBulkSearch" type="search" placeholder="Find a product or SKU…" aria-label="Find a bulk product"></div><form id="sfBulkQuickOrder"><div class="sf-table-wrap"><table class="sf-table"><thead><tr><th>Product</th><th>Unit price</th><th>Available</th><th>Quantity</th></tr></thead><tbody>'+(rows||'<tr><td colspan="4">No active products are available.</td></tr>')+'</tbody></table></div><div class="sf-blog-end"><button class="sf-btn" type="submit" '+(rows?"":"disabled")+'>Add selected products to basket</button><a class="sf-btn secondary" href="'+pageUrl("cart")+'">Review basket</a></div><p id="sfBulkQuickStatus" class="sf-help" role="status" aria-live="polite"></p></form></section>';}
function bulkEnquiryPage(){return pageHead("BUSINESS CUSTOMERS","Bulk & business enquiry","Request a formal supply quotation. Your enquiry is saved securely for the store team to review.")+quickOrderSheet()+'<form class="sf-form-card" id="sfBulkEnquiry"><div class="sf-form-grid"><div class="sf-field"><label for="sfBulkCompany">Business / company name *</label><input id="sfBulkCompany" name="company_name" required maxlength="180"></div><div class="sf-field"><label for="sfBulkContact">Contact person *</label><input id="sfBulkContact" name="contact_name" required maxlength="160"></div><div class="sf-field"><label for="sfBulkPhone">Business phone *</label><input id="sfBulkPhone" name="phone" required inputmode="tel" maxlength="24"></div><div class="sf-field"><label for="sfBulkEmail">Business email</label><input id="sfBulkEmail" name="email" type="email" maxlength="254"></div><div class="sf-field"><label for="sfBulkType">Business type</label><select id="sfBulkType" name="business_type"><option value="">Choose business type</option><option>Retail shop</option><option>Restaurant / café</option><option>Caterer</option><option>Institution</option><option>Distributor</option><option>Other</option></select></div><div class="sf-field"><label for="sfBulkTax">Tax / business ID</label><input id="sfBulkTax" name="tax_id" maxlength="100"></div><div class="sf-field full"><label for="sfBulkNeed">Products, pack sizes and quantities *</label><textarea id="sfBulkNeed" name="message" required minlength="5" maxlength="4000" placeholder="Example: Premium rice 25 kg × 20 bags&#10;Cooking oil 5 L × 12 cartons"></textarea></div><div class="sf-field full"><button class="sf-btn" id="sfBulkSubmit" type="submit">Submit quote request</button><small id="sfBulkStatus" role="status"></small></div></div></form>';}function returnsPage(){return pageHead("ORDER SUPPORT","Returns & refunds","Submit a return request for an order that has already been delivered. The store will review it and contact you.")+'<div class="sf-content-panel"><form id="sfReturnForm" class="sf-form-grid"><div class="sf-field"><label for="sfReturnOrder">Order number *</label><input id="sfReturnOrder" name="order" required maxlength="40" placeholder="HF-XXXXXXXXXX"></div><div class="sf-field"><label for="sfReturnPhone">Phone used at checkout *</label><input id="sfReturnPhone" name="phone" required maxlength="24" inputmode="tel"></div><div class="sf-field full"><label for="sfReturnReason">Reason for return *</label><textarea id="sfReturnReason" name="reason" required minlength="5" maxlength="1000"></textarea></div><div class="sf-field full"><label for="sfReturnNotes">Additional details (optional)</label><textarea id="sfReturnNotes" name="notes" maxlength="1000"></textarea></div><div class="sf-field full"><button class="sf-btn" id="sfReturnSubmit" type="submit">Submit return request</button><p id="sfReturnStatus" class="sf-help" role="status" aria-live="polite"></p></div></form><p class="sf-help">Order number and phone must match. Requests are accepted after delivery and reviewed by the store. Submission does not automatically approve a refund.</p></div>';}
function wishlistPage(){const rows=state.products.filter(p=>state.wishlist.includes(p.id));return pageHead("YOUR SAVED ITEMS","Wishlist","Keep the products you want to come back to.")+productGrid(rows);}
function renderFooter(){return '<footer class="sf-footer"><div class="sf-footer-inner"><div><h3>'+esc(state.website.brand?.name||templateInfo[state.website.template_key]?.brand||state.website.name)+'</h3><p>'+(esc(state.website.brand?.tagline||"Thoughtful products, clear choices and service you can count on."))+'</p></div><div><h4>Shop</h4><div class="sf-footer-links"><a href="'+pageUrl("shop")+'">All products</a><a href="'+pageUrl("cart")+'">Your basket</a><a href="'+pageUrl("wishlist")+'">Wishlist</a></div></div><div><h4>Help</h4><div class="sf-footer-links"><a href="'+pageUrl("contact")+'">Contact</a><a href="'+pageUrl("faq")+'">FAQs</a><a href="'+pageUrl("delivery")+'">Delivery</a><a href="'+pageUrl("returns")+'">Returns</a><a href="'+pageUrl("order-tracking")+'">Track order</a></div></div><div><h4>Information</h4><div class="sf-footer-links"><a href="'+pageUrl("about")+'">Our story</a><a href="'+pageUrl("offers")+'">Special offers</a><a href="'+pageUrl("brands")+'">Brands</a><a href="'+pageUrl("recipes")+'">Recipes</a><a href="'+pageUrl("journal")+'">Journal</a><a href="'+pageUrl("store-locator")+'">Find a store</a><a href="'+pageUrl("bulk-enquiry")+'">Business enquiry</a><a href="'+pageUrl("privacy")+'">Privacy</a><a href="'+pageUrl("terms")+'">Terms</a></div></div></div><div class="sf-footer-bottom">© '+new Date().getFullYear()+' '+esc(state.website.brand?.name||state.website.name)+'. All rights reserved.</div></footer>';}
function renderShell(){const brand=state.website.brand?.name||templateInfo[state.website.template_key]?.brand||state.website.name;const nav=[["home","Home"],["shop","Shop"],["offers","Offers"],["brands","Brands"],["recipes","Recipes"],["journal","Journal"],["about","Our story"],["store-locator","Find a store"],["delivery","Delivery"],["faq","FAQs"],["bulk-enquiry","Business"],["contact","Contact"],["order-tracking","Track order"]];const sampleCatalogue=Boolean(state.website.settings?.demo_catalog)||state.products.some(p=>Boolean(p.attributes?.demo)||!Boolean(p.attributes?.inventory_verified));return (preview?'<div class="sf-preview-bar"><strong>PRIVATE PREVIEW</strong> · This site is not public. Orders cannot be placed until it is published.</div>':'')+(sampleCatalogue?'<div class="sf-catalogue-notice" role="status"><strong>Catalogue preview</strong><span>Some products or stock details are sample/unverified. Ordering stays disabled until the store verifies its catalogue.</span></div>':'')+'<div class="sf-announcement">'+esc(state.website.brand?.announcement||"Thoughtful shopping · Reliable local service")+'</div><header class="sf-header"><div class="sf-header-inner"><a class="sf-brand" href="'+pageUrl("home")+'"><span class="sf-brand-mark">'+esc(brand.slice(0,2).toUpperCase())+'</span><span class="sf-brand-copy"><strong>'+esc(brand)+'</strong><small>'+esc(templateInfo[state.website.template_key]?.eyebrow||"ONLINE STORE")+'</small></span></a><form class="sf-search" id="sfHeaderSearch" role="search"><span>⌕</span><input name="q" placeholder="Search products and categories…" aria-label="Search products" autocomplete="off"><div class="sf-search-suggestions" id="sfSearchSuggestions" hidden></div></form><div class="sf-header-actions"><a class="sf-icon-btn" href="'+pageUrl("wishlist")+'">♡ Saved</a><a class="sf-cart-btn" href="'+pageUrl("cart")+'">Basket <span class="sf-cart-count">'+cartCount()+'</span></a><button class="sf-menu-btn" id="sfMenuToggle" aria-expanded="false" aria-label="Open menu">☰</button></div></div><nav class="sf-nav '+(state.mobileMenu?"is-open":"")+'" id="sfNav">'+nav.map(([key,label])=>'<a href="'+pageUrl(key)+'" '+(state.page===key?'aria-current="page"':'')+'>'+label+'</a>').join("")+'</nav></header>';}
function renderPage(){const key=state.page;switch(key){case"home":return hero();case"shop":return shopPage();case"category":return categoryPage();case"product":return productPage();case"search":return searchPage();case"cart":return cartPage();case"checkout":return checkoutPage();case"order-confirmation":return orderConfirmation();case"order-tracking":return trackingPage();case"wishlist":return wishlistPage();case"offers":return offersPage();case"brands":return brandsPage();case"recipes":return recipesPage();case"recipe-detail":return recipeDetailPage();case"journal":return journalPage();case"store-locator":return storeLocatorPage();case"bulk-enquiry":return bulkEnquiryPage();case"about":case"contact":case"faq":case"delivery":return contentPage(key);case"returns":return returnsPage();case"privacy":case"terms":case"account":return contentPage(key);default:{const doc=docFor(key);if(doc)return contentPage(key);return '<div class="sf-empty"><h3>Page not found</h3><p>This page is not available in the current site.</p><a class="sf-btn" href="'+pageUrl("home")+'">Go home</a></div>';}}}
function mobileDock(){return '<nav class="sf-mobile-dock" aria-label="Quick shopping navigation"><a href="'+pageUrl("home")+'" '+(state.page==="home"?'aria-current="page"':"")+'><span>⌂</span><small>Home</small></a><a href="'+pageUrl("shop")+'" '+(["shop","category"].includes(state.page)?'aria-current="page"':"")+'><span>▦</span><small>Shop</small></a><a href="'+pageUrl("search")+'" '+(state.page==="search"?'aria-current="page"':"")+'><span>⌕</span><small>Search</small></a><a href="'+pageUrl("wishlist")+'" '+(state.page==="wishlist"?'aria-current="page"':"")+'><span>♡</span><small>Saved</small></a><a href="'+pageUrl("cart")+'" '+(["cart","checkout"].includes(state.page)?'aria-current="page"':"")+'><span>▣<b>'+cartCount()+'</b></span><small>Basket</small></a></nav>';}
function searchSuggestions(query){const box=root.querySelector("#sfSearchSuggestions");if(!box)return;const q=String(query||"").trim().toLowerCase();if(!q){box.hidden=true;box.innerHTML="";return;}const matches=state.products.filter(p=>[p.name,p.sku,p.attributes?.brand,p.attributes?.origin,categoryName(p)].join(" ").toLowerCase().includes(q)).slice(0,6);box.innerHTML=matches.length?matches.map(p=>'<a class="sf-search-suggestion" href="'+pageUrl("product",{product:p.id})+'">'+(imageUrl(p)?'<img src="'+esc(imageUrl(p))+'" alt="" loading="lazy">':'<span class="sf-search-suggestion-fallback">'+esc(p.name.slice(0,1))+'</span>')+'<span><strong>'+esc(p.name)+'</strong><small>'+esc(categoryName(p))+' · '+money(p.price)+'</small></span><span class="sf-search-suggestion-arrow">↗</span></a>').join(""):'<div class="sf-search-no-results">No matching products. Press Enter to search the full catalogue.</div>';box.hidden=false;}
function render(){const brand=state.website.brand||{},template=state.website.template_key;document.body.dataset.template=template;document.title=(pageTitles[state.page]||"Store")+" · "+(brand.name||templateInfo[template]?.brand||state.website.name);const main=renderPage();root.innerHTML=renderShell()+'<main class="sf-main">'+main+'</main>'+renderFooter()+mobileDock();bind();}
function bind(){root.querySelector("#sfMenuToggle")?.addEventListener("click",()=>{state.mobileMenu=!state.mobileMenu;root.querySelector("#sfNav")?.classList.toggle("is-open",state.mobileMenu);root.querySelector("#sfMenuToggle")?.setAttribute("aria-expanded",String(state.mobileMenu));});root.querySelector("#sfHeaderSearch")?.addEventListener("submit",e=>{e.preventDefault();const q=new FormData(e.currentTarget).get("q")||"";location.href=pageUrl("search",{q});});root.querySelector("#sfHeaderSearch input[name=q]")?.addEventListener("input",e=>searchSuggestions(e.target.value));root.querySelector("#sfHeaderSearch input[name=q]")?.addEventListener("keydown",e=>{if(e.key==="Escape"){const box=root.querySelector("#sfSearchSuggestions");if(box)box.hidden=true;}});root.querySelector("#sfSearchForm")?.addEventListener("submit",e=>{e.preventDefault();const q=new FormData(e.currentTarget).get("q")||"";location.href=pageUrl("search",{q});});root.querySelector("#sfSort")?.addEventListener("change",e=>{state.filters.sort=e.target.value;const el=root.querySelector("#sfProductResults");if(el)el.innerHTML=productGrid(filteredProducts());bindDynamic();});root.querySelector("#sfBrandFilter")?.addEventListener("change",e=>{state.filters.brand=e.target.value;const el=root.querySelector("#sfProductResults");if(el)el.innerHTML=productGrid(filteredProducts());bindDynamic();});root.querySelector("#sfAvailabilityFilter")?.addEventListener("change",e=>{state.filters.availability=e.target.value;const el=root.querySelector("#sfProductResults");if(el)el.innerHTML=productGrid(filteredProducts());bindDynamic();});root.querySelector("#sfCheckoutForm")?.addEventListener("submit",submitOrder);root.querySelector("#sfArea")?.addEventListener("change",updateCheckoutSummary);root.querySelector("#sfTrackForm")?.addEventListener("submit",trackOrder);root.querySelector("#sfReturnForm")?.addEventListener("submit",submitReturnRequest);root.querySelector("#sfBulkQuickOrder")?.addEventListener("submit",submitBulkQuickOrder);root.querySelector("#sfBulkSearch")?.addEventListener("input",e=>{const q=e.target.value.toLowerCase();root.querySelectorAll("[data-bulk-row]").forEach(row=>row.hidden=!row.dataset.bulkName.includes(q));});root.querySelector("#sfBulkEnquiry")?.addEventListener("submit",submitQuote);bindDynamic();}
function bindDynamic(){root.querySelectorAll('[data-reorder-tracked]').forEach(b=>b.addEventListener('click',reorderTrackedOrder));root.querySelectorAll("[data-add]").forEach(b=>b.addEventListener("click",()=>addToCart(b.dataset.add)));root.querySelectorAll("[data-buy-now]").forEach(b=>b.addEventListener("click",()=>{addToCart(b.dataset.buyNow,Number(root.querySelector("#sfProductQty")?.value)||1,true);}));root.querySelectorAll("[data-wish]").forEach(b=>b.addEventListener("click",()=>toggleWish(b.dataset.wish)));root.querySelectorAll("[data-filter-category]").forEach(b=>b.addEventListener("click",()=>{state.filters.category=b.dataset.filterCategory;const el=root.querySelector("#sfProductResults");if(el)el.innerHTML=productGrid(filteredProducts());root.querySelectorAll("[data-filter-category]").forEach(x=>x.classList.toggle("is-active",x===b));bindDynamic();}));root.querySelectorAll("[data-cart-qty]").forEach(b=>b.addEventListener("click",()=>{const p=getProduct(b.dataset.product);changeCart(b.dataset.product,Number(b.dataset.cartQty)*(p?quantityStep(p):1));}));root.querySelectorAll("[data-cart-input]").forEach(input=>input.addEventListener("change",()=>{const p=getProduct(input.dataset.product),row=state.cart.find(x=>x.product_id===input.dataset.product);if(!p||!row)return;const value=Number(input.value),minimum=quantityMinimum(p);if(!Number.isFinite(value)||value<minimum||value>Number(p.stock)){notify("Enter a quantity between "+minimum+" and "+Number(p.stock)+".");render();return;}row.quantity=value;saveLocal();render();}));root.querySelectorAll("[data-remove]").forEach(b=>b.addEventListener("click",()=>{state.cart=state.cart.filter(x=>x.product_id!==b.dataset.remove);saveLocal();render();}));root.querySelectorAll("[data-qty]").forEach(b=>b.addEventListener("click",()=>{const input=root.querySelector("#sfProductQty");if(input){const step=Number(input.step)||1;input.value=Math.max(Number(input.min)||step,Math.min(Number(input.max)||999,Number(input.value||step)+Number(b.dataset.qty)*step));}}));}
function addToCart(id,quantity=1,buyNow=false){const p=getProduct(id);if(!canOrderProduct(p)){notify(p&&Number(p.stock)>0?"This item is in preview until the store verifies its inventory.":"This product is currently unavailable.");return;}const qty=Math.max(quantityMinimum(p),Number(quantity)||quantityMinimum(p));const row=state.cart.find(x=>x.product_id===id);const next=(row?.quantity||0)+qty;if(next>Number(p.stock)){notify("The requested quantity is not available in stock.");return;}if(row)row.quantity=next;else state.cart.push({product_id:id,quantity:qty});saveLocal();notify("Added to your basket.");if(buyNow)location.href=pageUrl("checkout");else render();}
function changeCart(id,delta){
const row=state.cart.find(x=>x.product_id===id),p=getProduct(id);if(!row)return;
if(!p||Number(p.stock)<=0){state.cart=state.cart.filter(x=>x.product_id!==id);notify("An unavailable product was removed from your basket.");}
else{const minimum=quantityMinimum(p);row.quantity=Math.max(minimum,Math.min(Number(p.stock),Number(row.quantity)+delta));if(row.quantity===minimum&&delta<0)notify("Minimum order quantity is "+minimum+". Use Remove to clear this item.");}
saveLocal();render();
}
function toggleWish(id){state.wishlist=state.wishlist.includes(id)?state.wishlist.filter(x=>x!==id):[...state.wishlist,id];saveLocal();notify(state.wishlist.includes(id)?"Saved to wishlist.":"Removed from wishlist.");render();}
async function submitReturnRequest(e){e.preventDefault();const form=e.currentTarget,box=root.querySelector("#sfReturnStatus"),btn=root.querySelector("#sfReturnSubmit"),data=new FormData(form);box.textContent="Submitting your request…";btn.disabled=true;try{const result=await storefrontApi().submitReturnRequest(siteSlug,String(data.get("order")||"").trim(),String(data.get("phone")||"").trim(),String(data.get("reason")||"").trim(),String(data.get("notes")||"").trim());box.textContent="Request received. Reference: "+String(result?.id||"submitted")+". The store will review your request and contact you.";form.reset();}catch(err){box.textContent=err.message||"Your return request could not be submitted. Please check the order details.";}finally{btn.disabled=false;}}
function submitBulkQuickOrder(e){e.preventDefault();const inputs=[...root.querySelectorAll("[data-bulk-qty]")],status=root.querySelector("#sfBulkQuickStatus");let added=0,skipped=0;for(const input of inputs){const quantity=Number(input.value||0);if(!Number.isFinite(quantity)||quantity<=0)continue;const p=getProduct(input.dataset.bulkQty);if(!canOrderProduct(p)){skipped++;continue;}const minimum=Math.max(1,Number(p.attributes?.minimum_order_quantity||1)),existing=state.cart.find(x=>x.product_id===p.id),next=Number(existing?.quantity||0)+quantity;if(quantity<minimum||next>Number(p.stock)){skipped++;continue;}if(existing)existing.quantity=next;else state.cart.push({product_id:p.id,quantity});added++;}if(added){saveLocal();status.textContent=added+" product line(s) added to your basket."+(skipped?" "+skipped+" line(s) skipped because of minimum quantity or stock limits.":"");}else status.textContent="Enter a valid quantity for at least one product. Check minimum quantities and available stock.";}
async function submitOrder(e){e.preventDefault();const error=root.querySelector("#sfCheckoutError"),btn=root.querySelector("#sfPlaceOrder");if(preview){error.textContent="Orders are disabled in private preview. Publish the website before accepting customer orders.";return;}if(!cartCount()){error.textContent="Your basket is empty.";return;}const blocked=state.cart.filter(x=>!canOrderProduct(getProduct(x.product_id)));if(blocked.length){error.textContent="Some basket items are still sample or unverified inventory. Remove them or wait until the store verifies the products.";return;}const form=new FormData(e.currentTarget);const area=String(form.get("area")||"").trim(),fee=deliveryFeeForArea(area),minimum=minimumOrderForArea(area);if(!area||fee===null){error.textContent="This store has not configured delivery for the selected area. Please choose a supported area.";return;}if(cartTotal()<minimum){error.textContent="The minimum order for this delivery area is "+money(minimum)+".";return;}const customer={name:String(form.get("name")||"").trim(),phone:String(form.get("phone")||"").trim()};const shipping={name:customer.name,phone:customer.phone,address:String(form.get("address")||"").trim(),area:String(form.get("area")||"").trim(),postcode:String(form.get("postcode")||"").trim()};const items=state.cart.map(x=>({product_id:x.product_id,quantity:x.quantity}));btn.disabled=true;btn.textContent="Submitting order…";error.textContent="";try{const result=await storefrontApi().placeOrder(siteSlug,items,customer,shipping,[String(form.get("notes")||"").trim(),form.get("substitution")?"Substitution preference: "+String(form.get("substitution")):""].filter(Boolean).join("\n").slice(0,2000));state.lastOrder=result;try{sessionStorage.setItem("hf-last-order:"+siteSlug,JSON.stringify(result));}catch(_){}state.cart=[];saveLocal();location.href=pageUrl("order-confirmation",{order:result.order_number});}catch(err){error.textContent=err.message||"Order could not be submitted. Please check your details and try again.";btn.disabled=false;btn.textContent="Place COD order";}}
async function trackOrder(e){e.preventDefault();const form=new FormData(e.currentTarget),box=root.querySelector("#sfTrackResult");box.textContent="Checking order…";try{const result=await storefrontApi().trackOrder(siteSlug,String(form.get("order")||"").trim(),String(form.get("phone")||"").trim());if(!result){state.lastTrackedOrder=null;box.innerHTML='<p role="alert">No order matched those details. Check the order number and phone number.</p>';return;}state.lastTrackedOrder=result;const statuses=["pending","processing","shipped","delivered"],current=statuses.indexOf(result.status);box.innerHTML='<div class="sf-content-panel"><span class="sf-kicker">ORDER '+esc(result.order_number)+'</span><h2>Current status: '+esc(result.status)+'</h2><p>Total '+money(result.total)+' · Payment '+esc(result.payment_status)+'</p><div class="sf-timeline">'+statuses.map((s,i)=>'<span class="'+(i<=current?"is-done":"")+'">'+s+'</span>').join("")+'</div><ul>'+result.items.map(x=>'<li>'+esc(x.product?.name||"Product")+' × '+esc(x.quantity)+' — '+money(x.line_total)+'</li>').join("")+'</ul>'+(result.items?.length?'<button type="button" class="sf-btn" data-reorder-tracked>Buy these items again</button>':"")+'</div>';bindDynamic();}catch(err){state.lastTrackedOrder=null;box.textContent=err.message||"Order lookup failed.";}}
function reorderTrackedOrder(){const items=state.lastTrackedOrder?.items||[],ready=[];for(const item of items){const id=item.product?.id,p=getProduct(id),quantity=Number(item.quantity||0);if(!p||quantity<=0||quantity<Number(p.attributes?.minimum_order_quantity||1))continue;const current=state.cart.find(x=>x.product_id===id),next=(current?.quantity||0)+quantity;if(next>Number(p.stock))continue;ready.push({id,quantity});}if(!ready.length){notify("The previous order's products are no longer available in the required quantities.");return;}for(const item of ready){const row=state.cart.find(x=>x.product_id===item.id);if(row)row.quantity+=item.quantity;else state.cart.push({product_id:item.id,quantity:item.quantity});}saveLocal();notify("Available items from your previous order were added to the basket.");location.href=pageUrl("cart");}
async function submitQuote(e){e.preventDefault();const form=e.currentTarget,status=root.querySelector("#sfBulkStatus"),button=root.querySelector("#sfBulkSubmit"),data=new FormData(form);if(preview){status.textContent="Quote submissions are disabled in private preview. Use the isolated QA workflow for acceptance testing.";return;}button.disabled=true;status.textContent="Saving your quote request…";try{const message=String(data.get("message")||"").trim(),items=message.split(/\r?\n/).map(line=>line.trim()).filter(Boolean).slice(0,100).map(description=>({description:description.slice(0,500)}));const business={company_name:String(data.get("company_name")||"").trim(),contact_name:String(data.get("contact_name")||"").trim(),phone:String(data.get("phone")||"").trim(),email:String(data.get("email")||"").trim(),business_type:String(data.get("business_type")||""),tax_id:String(data.get("tax_id")||"").trim()};if(!items.length)throw new Error("Add at least one product and quantity line.");const result=await storefrontApi().submitQuoteRequest(siteSlug,business,items,message.slice(0,2000));status.textContent=(result?.message||"Your quote request has been received.")+" Reference: "+(result?.quote_number||"saved");form.reset();}catch(err){status.textContent=err.message||"Your quote request could not be saved. Please try again.";}finally{button.disabled=false;}}
async function getPreviewToken(){if(!preview)return null;const client=await window.HFNeonClientReady;if(!client)throw new Error("Independent storefront authentication is unavailable.");const {data,error}=await client.auth.getSession();if(error||!(data?.session?.user?.id||data?.user?.id))throw new Error("Sign in to the website workspace to preview this draft.");return null;}
async function boot(){if(!siteSlug){throw new Error("A storefront site address is required.");}state.previewToken=await getPreviewToken();const data=await storefrontApi().loadStorefrontData(siteSlug,{token:state.previewToken,preview});state.website=data.website;state.pages=data.pages;state.documents=data.documents;state.categories=data.categories;state.products=data.products;state.deliveryZones=data.deliveryZones||[];state.priceTiers=data.priceTiers||[];state.page=params.get("page")||"home";if(!state.pages.some(p=>p.page_key===state.page)&&!state.documents.some(d=>d.page_key===state.page))state.page="home";if(state.website.status!=="published"||preview){let robots=document.querySelector('meta[name="robots"]');if(!robots){robots=document.createElement("meta");robots.name="robots";document.head.appendChild(robots);}robots.content="noindex,nofollow";}loadLocal();render();}
boot().catch(err=>{console.error("Storefront load failed",err);root.innerHTML='<main class="sf-main"><div class="sf-empty"><h3>Storefront could not be opened</h3><p>'+esc(err.message||"Please try again later.")+'</p>'+(preview?'<a class="sf-btn" href="./admin/website-pages.html">Back to Website Pages</a>':'')+'</div></main>';});
})();